begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,review_id uuid,approval_id uuid,input jsonb);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),null);
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'ReviewFlow rights rollback fixture' from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'ReviewFlow other rights rollback fixture' from fixture;
insert into public.reviews(id,property_id,platform,reviewer_name,review_text,rating)select review_id,property_id,'other','Fixture resident','A peaceful community',5 from fixture;
create function pg_temp.input() returns jsonb language plpgsql as $$declare f fixture;s jsonb;begin select * into f from fixture;s:=public.read_reviewflow_testimonial_source(f.property_id,f.actor_id,f.review_id);return jsonb_build_object('action','approve','reviewId',f.review_id,'sourceVersion',s->'source'->'sourceVersion','sourceHash',s->>'sourceHash','attributionApproved',true,'rightsBasis','direct_consent','evidenceNote','Retained isolated consent evidence','usageScope','["website"]'::jsonb,'expiresAt',null,'reason','Reviewed exact source and permitted use');end$$;
update fixture set input=pg_temp.input();
do $$declare f fixture;r jsonb;collision uuid:=gen_random_uuid();begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.decide_reviewflow_testimonial(uuid,uuid,uuid,jsonb)','execute') and not has_table_privilege('authenticated','public.review_testimonial_approvals','update'),'direct clients cannot rewrite permission evidence');
 perform pg_temp.check(public.read_reviewflow_testimonial_source(f.property_id,gen_random_uuid(),f.review_id)->>'state'='forbidden' and public.decide_reviewflow_testimonial(gen_random_uuid(),f.property_id,gen_random_uuid(),f.input)->>'state'='forbidden','current property membership is required on reads and decisions');
 perform pg_temp.check(public.read_reviewflow_testimonial_source(f.other_property,f.actor_id,f.review_id)->>'state'='not_found','source reads cannot cross property scope');
 perform pg_temp.check(public.read_reviewflow_testimonial_source(f.property_id,f.actor_id,f.review_id)->'sourceIssue'='null'::jsonb,'an unknown original review date remains unknown and does not block permission recording');
 perform public.append_shared_action_event(collision,collision,f.property_id,f.actor_id,'reviewflow','review.analysis.requested','server_confirmed','succeeded','{}',null,null,'{}');
 begin perform public.decide_reviewflow_testimonial(collision,f.property_id,f.actor_id,f.input);raise exception 'Expected action collision';exception when others then if sqlerrm='Expected action collision' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.review_testimonial_approvals where id=collision),'rights and action history save atomically');
 perform pg_temp.check(public.decide_reviewflow_testimonial(gen_random_uuid(),f.property_id,f.actor_id,f.input||jsonb_build_object('expiresAt',now()-interval '1 day'))->>'state'='invalid_expiry','past expiry is a visible validation issue, not an unconfirmed save');
 r:=public.decide_reviewflow_testimonial(f.approval_id,f.property_id,f.actor_id,f.input);perform pg_temp.check(r->>'state'='saved','the exact source permission is saved');
 perform pg_temp.check(public.decide_reviewflow_testimonial(f.approval_id,f.property_id,f.actor_id,f.input)->>'state'='replayed' and(select count(*)=1 from public.review_testimonial_approvals where review_id=f.review_id),'lost approval responses recover the same permission');
 perform pg_temp.check(public.decide_reviewflow_testimonial(f.approval_id,f.property_id,f.actor_id,f.input||'{"reason":"Different decision"}')->>'state'='request_conflict','saved identities cannot silently change their evidence');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where id=f.approval_id and action='review.testimonial.approved'),'one manager decision is attributed to the approval');
 perform pg_temp.check((select count(*)=1 from public.eligible_reviewflow_testimonials(f.property_id,'website')) and(select count(*)=0 from public.eligible_reviewflow_testimonials(f.property_id,'social')),'website permission is not assumed to authorize social marketing');
 perform pg_temp.check(public.read_forgestudio_source_record(f.property_id,'testimonial',f.approval_id) is null,'ForgeStudio source checks reject a website-only permission');
 begin update public.review_testimonial_approvals set review_text_snapshot='Rewritten consent text' where id=f.approval_id;raise exception 'Expected immutable permission';exception when others then if sqlerrm='Expected immutable permission' then raise;end if;end;
 perform pg_temp.check((select review_text_snapshot='A peaceful community' from public.review_testimonial_approvals where id=f.approval_id),'approved source text cannot be rewritten');
 perform pg_temp.check(public.decide_reviewflow_testimonial(gen_random_uuid(),f.property_id,f.actor_id,f.input)->>'state'='active_approval','a second active approval requires revoking the original');
 update public.reviews set review_text='A corrected source review' where id=f.review_id;
 perform pg_temp.check((select count(*)=0 from public.eligible_reviewflow_testimonials(f.property_id,'website')),'changed sources stop new reuse before any explicit revocation');
 perform pg_temp.check(public.read_reviewflow_testimonial_source(f.property_id,f.actor_id,f.review_id)->'activeApproval'->>'eligibility'='source_changed','outdated permissions remain visible with their original evidence');
 perform pg_temp.check(public.decide_reviewflow_testimonial(f.approval_id,f.property_id,f.actor_id,f.input)->>'state'='replayed','recovering an old approval does not create consent for a changed source');
 perform pg_temp.check(public.decide_reviewflow_testimonial(gen_random_uuid(),f.property_id,f.actor_id,f.input)->>'state'='stale_source','an unreviewed source correction cannot receive stale approval');
end$$;
do $$declare f fixture;r jsonb;payload jsonb;command_id uuid:=gen_random_uuid();begin select * into f from fixture;
 payload:=jsonb_build_object('action','revoke','reviewId',f.review_id,'approvalId',f.approval_id,'expectedVersion',1,'reason','Consent withdrawn; published uses require separate review');
 perform pg_temp.check(public.decide_reviewflow_testimonial(gen_random_uuid(),f.property_id,f.actor_id,payload||'{"expectedVersion":99}')->>'state'='stale_approval','revocation requires the exact saved permission version');
 update public.reviews set reviewer_name=null,rating=null,review_text='' where id=f.review_id;
 r:=public.decide_reviewflow_testimonial(command_id,f.property_id,f.actor_id,payload);perform pg_temp.check(r->>'state'='saved' and r->'publishedContentChanged'='false'::jsonb,'revocation works even when the source becomes incomplete and does not pretend published content was removed');
 perform pg_temp.check(public.decide_reviewflow_testimonial(command_id,f.property_id,f.actor_id,payload)->>'state'='replayed','a lost revocation response recovers once');
 perform pg_temp.check((select version=2 and status='revoked' and review_text_snapshot='A peaceful community' from public.review_testimonial_approvals where id=f.approval_id),'revocation retains original permission and source evidence');
 begin update public.review_testimonial_approvals set status='active',revoked_at=null,revoked_by=null,revocation_reason=null where id=f.approval_id;raise exception 'Expected immutable revocation';exception when others then if sqlerrm='Expected immutable revocation' then raise;end if;end;
 perform pg_temp.check((select status='revoked' from public.review_testimonial_approvals where id=f.approval_id),'revoked permission cannot regain approval by changing a flag');
 update public.reviews set reviewer_name='Fixture resident',rating=5,review_text='Current exact testimonial' where id=f.review_id;
 payload:=pg_temp.input()||'{"usageScope":["website","social"]}';command_id:=gen_random_uuid();perform public.decide_reviewflow_testimonial(command_id,f.property_id,f.actor_id,payload);
 perform pg_temp.check((select count(*)=1 from public.eligible_reviewflow_testimonials(f.property_id,'social')) and public.read_forgestudio_source_record(f.property_id,'testimonial',command_id)->>'source_version'=(select source_version::text from public.reviews where id=f.review_id),'new scoped approval reaches ForgeStudio with exact-source evidence');
 perform pg_temp.check((select count(*)=2 from public.review_testimonial_approvals where review_id=f.review_id),'replacement approval retains prior consent history');
 perform pg_temp.check((select count(*)=0 from public.eligible_reviewflow_testimonials(f.other_property,'website')),'eligible testimonial reads stay property-scoped');
 begin delete from public.review_testimonial_approvals where id=f.approval_id;raise exception 'Expected retained history';exception when others then if sqlerrm='Expected retained history' then raise;end if;end;
 perform pg_temp.check((select count(*)=2 from public.review_testimonial_approvals where review_id=f.review_id),'permission history is not deletable while its property exists');
end$$;
do $$declare f fixture;r public.reviews;begin select * into f from fixture;
 insert into public.reviews(property_id,platform,reviewer_name,review_text,rating)values(f.property_id,'other','Expired fixture resident','A past consent fixture',5)returning * into r;
 insert into public.review_testimonial_approvals(review_id,property_id,source_version,content_fingerprint,reviewer_name_snapshot,review_text_snapshot,rating_snapshot,platform_snapshot,review_date_snapshot,approved_by,rights_basis,attribution_approved,usage_scope,expires_at)values(r.id,r.property_id,r.source_version,public.crm_configuration_hash(public.reviewflow_testimonial_source(r)),r.reviewer_name,r.review_text,r.rating,r.platform,r.review_date,f.actor_id,'direct_consent',true,'["website","social"]',now()-interval '1 day');
 perform pg_temp.check(public.read_reviewflow_testimonial_source(f.property_id,f.actor_id,r.id)->'activeApproval'->>'eligibility'='expired','expired evidence remains visible and explicitly unavailable');
 perform pg_temp.check(not exists(select 1 from public.eligible_reviewflow_testimonials(f.property_id,'website')where review_id=r.id),'expired permissions do not feed new website content');
 begin insert into public.review_testimonial_approvals(review_id,property_id,content_fingerprint,reviewer_name_snapshot,review_text_snapshot,rating_snapshot,platform_snapshot,approved_by,rights_basis,attribution_approved)values(r.id,r.property_id,repeat('a',64),r.reviewer_name,r.review_text,r.rating,r.platform,f.actor_id,'direct_consent',true);raise exception 'Expected exact-source guard';exception when others then if sqlerrm='Expected exact-source guard' then raise;end if;end;
 perform pg_temp.check((select count(*)=1 from public.review_testimonial_approvals where review_id=r.id),'new unversioned legacy-style approvals are rejected');
end$$;
select count(*) as passed_assertions from checks;
rollback;
